/** T-131 phase 2: a per-spot correction of the v1 surf height (offshore swell carried to 10 m), fitted against REAL buoy observations.
 *  Evidence: docs/forecast/ACCURACY-VS-BUOYS.md (generated by docs/forecast/data/accuracy-vs-buoys.ts; numbers in docs/forecast/data/accuracy-vs-buoys.json).
 *  How each factor was made: a buoy within 40 km where CDIP MOP is shown to be right (MOP at the buoy's own site within 0.5 ft bias and 1 ft MAE, judged on
 *  the fit hours) is carried to the spot's MOP point by MOP's own hourly ratio (point ÷ buoy site); v1 is compared with that observation-anchored height.
 *  The factor (median anchored ÷ v1) was fitted on the first 2/3 of the archive hours, held out on the last 1/3, and checked again, unchanged, on
 *  2026-10-07 to 2026-11-06. It is applied only in the offshore-Hs size bins where it held (section 3b), and only at spots listed here. This is OUR
 *  correction, labelled as such wherever the number is shown, and it is not a measurement at the spot. */
export interface BuoyTransfer {
  spotId: string; factor: number; buoyId: string; buoyName: string; km: number;
  /** the spot's MOP point and how it was chosen (the anchored height is at this point, not at the break) */ mopId: string; mopStatus: string;
  fit: {from: string; to: string};
  heldOut: {from: string; to: string; n: number; maeBeforeFt: number; maeAfterFt: number};
  /** the later window (doc only, not shown on screen) */ later: {from: string; to: string; n: number; maeBeforeFt: number; maeAfterFt: number};
  /** offshore total Hs bins [from, to) in ft where the factor held; to = null means no upper bound */ bins: [number, number | null][];
}
export const BUOY_TRANSFER_REF = 'docs/forecast/ACCURACY-VS-BUOYS.md';
const LATER = {from: '2026-10-07', to: '2026-11-06'};
/** The factors the evidence supports (verdict "supported" in ACCURACY-VS-BUOYS.md section 3, bins from section 3b), minus HELD. src/tests/buoy-transfer.test.ts keeps them equal to the generated JSON. */
export const BUOY_TRANSFERS: BuoyTransfer[] = [
  {spotId: 'spot-2', factor: 1.482, buoyId: '142', buoyName: 'San Francisco Bar', km: 11.2, mopId: 'SF023', mopStatus: 'the point CDIP documents for Ocean Beach',
    fit: {from: '2025-11-01', to: '2026-01-26'}, heldOut: {from: '2026-01-26', to: '2026-04-28', n: 725, maeBeforeFt: 2.57, maeAfterFt: 0.81}, later: {...LATER, n: 212, maeBeforeFt: 1.94, maeAfterFt: 0.68}, bins: [[0, 4], [4, 8], [8, 12]]},
  {spotId: 'spot-4', factor: 0.774, buoyId: '142', buoyName: 'San Francisco Bar', km: 28.9, mopId: 'SM340', mopStatus: 'assigned by the facing-match rule, not reviewed',
    fit: {from: '2025-11-01', to: '2026-01-29'}, heldOut: {from: '2026-01-29', to: '2026-04-28', n: 782, maeBeforeFt: 1.29, maeAfterFt: 0.53}, later: {...LATER, n: 277, maeBeforeFt: 1.12, maeAfterFt: 0.43}, bins: [[4, 8], [8, 12]]},
  {spotId: 'cs-topanga', factor: 0.782, buoyId: '028', buoyName: 'Santa Monica Bay', km: 20.5, mopId: 'L0809', mopStatus: 'assigned by the facing-match rule, not reviewed',
    fit: {from: '2025-11-01', to: '2026-03-26'}, heldOut: {from: '2026-03-26', to: '2026-04-29', n: 351, maeBeforeFt: 0.5, maeAfterFt: 0.19}, later: {...LATER, n: 572, maeBeforeFt: 0.75, maeAfterFt: 0.32}, bins: [[0, 4]]},
];
/** Supported by the evidence but deliberately NOT applied (data-honesty review, 2026-11-06). Kept as candidates in the doc. */
export const HELD_TRANSFERS: {spotId: string; factor: number; reason: string}[] = [
];
export const buoyTransferFor = (spotId: string) => BUOY_TRANSFERS.find((t) => t.spotId === spotId) ?? null;
/** The transfer that applies to one hour: the spot has one AND the hour's offshore total Hs (ft) falls in a bin where it held. Otherwise null (v1 uncorrected). */
export function buoyTransferAt(spotId: string, offshoreHsFt: number | null | undefined): BuoyTransfer | null {
  const t = buoyTransferFor(spotId); if (!t || typeof offshoreHsFt !== 'number' || !Number.isFinite(offshoreHsFt)) return null;
  return t.bins.some(([a, b]) => offshoreHsFt >= a && (b === null || offshoreHsFt < b)) ? t : null;
}

/** The Komar-Gaughan breaking height used by v1 grows as Hs^0.8 (H_b ∝ (T·H²)^0.4), so a factor f on the surf height is f^0.8 on the breaking height. */
export const breakingFactor = (f: number) => f ** 0.8;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const d = (iso: string, year = true) => { const [y, m, dd] = iso.split('-').map(Number); return `${dd} ${MONTHS[m - 1]}${year ? ` ${y}` : ''}`; };
const binsText = (b: BuoyTransfer['bins']) => { const lo = Math.min(...b.map((x) => x[0])), hi = b.some((x) => x[1] === null) ? null : Math.max(...b.map((x) => x[1]!)); return lo === 0 && hi === null ? 'at all sizes' : `only with offshore waves ${lo > 0 ? `of ${lo}` : 'under'}${lo > 0 ? (hi === null ? ' ft and up' : `–${hi} ft`) : ` ${hi} ft`}`; };
/** The short visible tag beside "model estimate". */
export const buoyTransferTag = (t: Pick<BuoyTransfer, 'factor'>) => `buoy-corrected ×${t.factor.toFixed(2)}`;
/** One line for the method label: what was corrected, by how much, against what, on which held-out dates, and where it applies. */
export function buoyTransferText(t: BuoyTransfer): string {
  return `${buoyTransferTag(t)} (our correction): fitted ${d(t.fit.from)}–${d(t.fit.to)} on measured waves at the CDIP ${t.buoyId} ${t.buoyName} buoy (${t.km.toFixed(0)} km away) carried to MOP point ${t.mopId} (${t.mopStatus}) by CDIP's model; against that buoy height carried to MOP point ${t.mopId}, on held-out hours ${d(t.heldOut.from, false)}–${d(t.heldOut.to)}, the typical error fell from ${t.heldOut.maeBeforeFt.toFixed(1)} to ${t.heldOut.maeAfterFt.toFixed(1)} ft; applied ${binsText(t.bins)}`;
}
